messages.content:
Tool response:
Tool: create_rate_plan
Description: Creates a new rate plan with the specified parameters. 
The rate plan will apply to all site types as requested.
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name",
          "description": "Name of the rate plan"
        },
        "description": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Description",
          "description": "Description of the rate plan"
        },
        "discount_percent": {
          "type": "number",
          "maximum": 100.0,
          "minimum": 0.0,
          "title": "Discount Percent",
          "description": "Discount percentage offered by the rate plan"
        },
        "min_nights": {
          "type": "integer",
          "exclusiveMinimum": 0.0,
          "title": "Min Nights",
          "description": "Minimum number of nights required to qualify for the rate plan"
        },
        "valid_from": {
          "type": "string",
          "title": "Valid From",
          "description": "Start date when the rate plan becomes valid (YYYY-MM-DD)"
        },
        "valid_to": {
          "type": "string",
          "title": "Valid To",
          "description": "End date when the rate plan expires (YYYY-MM-DD)"
        }
      },
      "required": [
        "name",
        "discount_percent",
        "min_nights",
        "valid_from",
        "valid_to"
      ]
    }
